"""Read-only assertions plus rolled-back trigger tests against the CMS."""
import subprocess
script=r'''const {Pool}=require('pg');(async()=>{const p=new Pool({connectionString:process.env.DB_VIBERS_MAIN_URL,max:1});const d=await p.connect();try{await d.query('BEGIN');const r=await d.query("SELECT payload FROM semologo.logo_posts WHERE id='hypernix' FOR UPDATE");const original=r.rows[0].payload;const count=async()=>Number((await d.query("SELECT count(*) n FROM semologo.logo_versions WHERE brand_id='hypernix'")).rows[0].n);const before=await count();await d.query("UPDATE semologo.logo_posts SET payload=jsonb_set(payload,'{presentation}',$1::jsonb) WHERE id='hypernix'",[JSON.stringify({file:'logo.png',bg:'light'})]);if(await count()!==before)throw Error('Presentation falsely created a logo revision');await d.query("UPDATE semologo.logo_posts SET payload=jsonb_set(payload,'{logo_png}',to_jsonb('sources/test-rollback.png'::text)) WHERE id='hypernix'");if(await count()!==before+1)throw Error('Asset change not archived');const current=await d.query("SELECT count(*)::int n FROM semologo.logo_versions WHERE brand_id='hypernix' AND is_current");if(current.rows[0].n!==1)throw Error('Multiple current revisions');await d.query("UPDATE semologo.logo_posts SET payload=$1 WHERE id='hypernix'",[JSON.stringify(original)]);await d.query('ROLLBACK');console.log('PASS archive trigger preserves previous assets, presentation is separate, exactly one current version; all test changes rolled back');}catch(e){await d.query('ROLLBACK');throw e;}finally{d.release();await p.end();}})().catch(e=>{console.error(e.message);process.exitCode=1});'''
subprocess.run(['ssh','vibers','docker exec -i semologo node -'],input=script,text=True,check=True)
